// 05 helper: resolve what a user or agent calls a module to Module ids, for the tools that take
// a module (find_experts, module_owners, impact_radius). Matches, best first:
//   rank 0  the exact id               module:FalkorDB:graph/src/index
//   rank 1  the exact path             graph/src/index
//   rank 2  a path ending in /$q       index -> graph/src/index (and proofs/index, if any)
// Ties go to the module with the most current expertise (sum of decayed EXPERT_IN scores):
// on FalkorDB "index" matches both src/index (C engine, dormant) and graph/src/index (Rust).
// $q is lowercased by the caller; ids and paths are compared lowercased. Module is small
// (135 on FalkorDB), so the scan is cheap.
// FalkorDB fix: without the parentheses, `a = $q OR p ENDS WITH '/' + $q` fails with
// "Type mismatch: expected Boolean but was String" (the + binds differently than in Neo4j).
MATCH (m:Module)
WITH m, toLower(m.id) AS mid, toLower(m.path) AS mpath
WHERE (mid = $q) OR (mpath = $q) OR (mpath ENDS WITH ('/' + $q))
WITH m, CASE WHEN mid = $q THEN 0 WHEN mpath = $q THEN 1 ELSE 2 END AS rank
OPTIONAL MATCH (:Person)-[e:EXPERT_IN]->(m)
WITH m, rank, sum(coalesce(e.score, 0.0)) AS activity
RETURN m.id AS id, m.path AS path, m.repo AS repo, rank, activity
ORDER BY rank ASC, activity DESC, size(m.path) ASC
LIMIT $limit

// 06 F3 owners of one module: CODEOWNERS owners (people and teams) vs active experts.
// Feeds the module_owners tool. Only the module's own OWNS edges count; owners are NOT
// inherited from parent modules (FalkorDB's root "/" entry is the CODEOWNERS file
// itself, not a catch-all). No OWNS edge -> listed_owner = false, i.e. "no listed owner" (golden q08).
// paper = true for a person owner with no touch in 12 months, or a team none of whose
// known members has touched the module (a team with no known members is never paper).
MATCH (m:Module {id: $module})
OPTIONAL MATCH (o)-[:OWNS]->(m)
OPTIONAL MATCH (o)-[oe:EXPERT_IN]->(m)
OPTIONAL MATCH (member:Person)-[:MEMBER_OF]->(o)
OPTIONAL MATCH (member)-[me:EXPERT_IN]->(m)
WHERE me.last_touch >= $now - 31536000
WITH m, o, oe, count(DISTINCT member) AS n_members, count(DISTINCT me) AS active_members
WITH m, collect(CASE WHEN o IS NULL THEN null ELSE {
       id: o.id, kind: labels(o)[0], name: coalesce(o.login, o.name),
       members: n_members,
       paper: CASE WHEN labels(o)[0] = 'Team' THEN n_members > 0 AND active_members = 0
                   ELSE oe IS NULL OR oe.last_touch < $now - 31536000 END
     } END) AS owners
OPTIONAL MATCH (x:Person)-[xe:EXPERT_IN]->(m)
WHERE xe.score > 0.5
WITH m, owners, x, xe ORDER BY xe.score DESC
WITH m, owners,
     collect({id: x.id, person: coalesce(x.login, x.name), score: xe.score, last_touch: xe.last_touch})[0..3] AS experts
RETURN m.id AS module_id, m.path AS module, size(owners) > 0 AS listed_owner, owners,
       experts AS active_experts

// 05 F2 who-knows: top experts on a module, with evidence links.
// Changed from the plan: evidence is the PRs that CONTAIN the person's commits on the
// module, not PRs they authored. Commit-only authors (sandbox Marta, Priya) and people
// whose commits went in under someone else's PR otherwise show no evidence.
// Reviewed PRs on the module are returned too (evidence_reviews), so someone whose score
// comes only from reviews still has a link to show. They're collected in a separate
// WITH stage to avoid multiplying the commit rows.
// $since (epoch seconds, 0 for all time) keeps only people whose last touch is that recent.
// FalkorDB keeps the input order inside collect(), so ORDER BY before collecting
// puts the most recent PRs and commits first.
MATCH (p:Person)-[e:EXPERT_IN]->(m:Module {id: $module})
WHERE e.score > 0.5 AND coalesce(e.last_touch, 0) >= $since
OPTIONAL MATCH (p)-[:AUTHORED]->(c:Commit)-[:TOUCHES]->(m)
WHERE NOT coalesce(c.bulk, false)
OPTIONAL MATCH (c)-[:PART_OF]->(pr:PullRequest)
WITH p, e, m, c, pr ORDER BY c.at DESC
WITH p, e, m, collect(DISTINCT pr.url) AS prs, collect(DISTINCT c.id) AS commits
OPTIONAL MATCH (p)-[r:REVIEWED]->(rpr:PullRequest)<-[:PART_OF]-(rc:Commit)-[:TOUCHES]->(m)
WHERE NOT coalesce(rc.bulk, false) AND NOT (p)-[:AUTHORED]->(rpr)
WITH p, e, prs, commits, rpr ORDER BY rpr.merged_at DESC
WITH p, e, prs, commits, collect(DISTINCT rpr.url) AS reviewed_prs
RETURN p.id AS person_id, coalesce(p.login, p.name) AS person, p.name AS name,
       e.score AS score, e.authored AS authored, e.reviewed AS reviewed,
       e.commits AS commits, e.reviews AS reviews, e.last_touch AS last_touch,
       prs[0..3] AS evidence, commits[0..3] AS evidence_commits,
       reviewed_prs[0..3] AS evidence_reviews
ORDER BY score DESC LIMIT 5

